struct SharedDynamicWorker { void *batch_scratch=nullptr; /* mode 8 device scratch, Q38_SBATCH_SCRATCH_BYTES */ SharedResidentControl *host=nullptr,*device=nullptr;SharedResidentReturn *out=nullptr,*out_device=nullptr;SharedResidentGrid* grid=nullptr;Weights* table=nullptr;float* partial=nullptr;const uint8_t*ple_table=nullptr;uint64_t ple_bytes=0;cudaStream_t stream=nullptr;unsigned seq=0;bool running=false; };
static bool shared_await(volatile unsigned*p,unsigned value,int timeout_ms){auto end=std::chrono::steady_clock::now()+std::chrono::milliseconds(timeout_ms);while(std::chrono::steady_clock::now()<end){if(*p==value){std::atomic_thread_fence(std::memory_order_seq_cst);return true;}std::this_thread::yield();}return false;}
static void shared_publish(SharedDynamicWorker&w,unsigned seq){_mm_sfence();std::atomic_thread_fence(std::memory_order_seq_cst);w.host->seq=seq;_mm_sfence();}
struct SharedKernelImage { CUmodule module=nullptr; CUfunction function=nullptr; };
struct PleDevice { uint64_t bytes=0; std::string handle; };
static std::string ple_canon(std::string s){auto p=s.find(':');if(p!=std::string::npos)s=s.substr(p+1);std::transform(s.begin(),s.end(),s.begin(),[](unsigned char c){return char(std::tolower(c));});return s;}
static std::map<std::string,PleDevice> read_ple_devices(const char*path){std::map<std::string,PleDevice>m;if(!path||!*path)return m;std::ifstream f(path);if(!f)throw std::runtime_error("cannot open PLE IPC manifest");std::string l;while(std::getline(f,l)){std::istringstream s(l);std::string k,o,b,bytes,h;if(!(s>>k)||k!="DEVICE")continue;if(!(s>>o>>b>>bytes>>h))throw std::runtime_error("malformed PLE IPC device row");if(o=="cuda_ordinal")continue;m[ple_canon(b)]={std::stoull(bytes),h};}return m;}
static void import_ple_table(SharedDynamicWorker&v,unsigned d,const std::map<std::string,PleDevice>&m){char bdf[32]{};CK(cudaDeviceGetPCIBusId(bdf,sizeof(bdf),int(d)));auto it=m.find(ple_canon(bdf));if(it==m.end()||!it->second.bytes)return;const char*manifest=std::getenv("Q38_PLE_IPC_MANIFEST");if(!manifest||!*manifest)throw std::runtime_error("PLE manifest path missing");auto hp=std::filesystem::path(manifest).parent_path()/it->second.handle;cudaIpcMemHandle_t h{};std::ifstream f(hp,std::ios::binary);if(!f.read(reinterpret_cast<char*>(&h),sizeof(h)))throw std::runtime_error("cannot read PLE IPC handle for "+std::string(bdf));void*p=nullptr;CK(cudaIpcOpenMemHandle(&p,h,cudaIpcMemLazyEnablePeerAccess));v.ple_table=static_cast<const uint8_t*>(p);v.ple_bytes=it->second.bytes;}
static void shared_check_driver(CUresult r,const char*where){if(r!=CUDA_SUCCESS){const char*name="unknown";cuGetErrorName(r,&name);throw std::runtime_error(std::string(where)+": "+name);}}
static std::vector<SharedKernelImage> load_shared_kernel_image(const std::string&path,int count){std::vector<SharedKernelImage> staged(count);try{for(int d=0;d<count;d++){CK(cudaSetDevice(d));shared_check_driver(cuModuleLoad(&staged[d].module,path.c_str()),"cuModuleLoad shared kernel");shared_check_driver(cuModuleGetFunction(&staged[d].function,staged[d].module,"resident_dynamic_shared"),"cuModuleGetFunction shared kernel");}}catch(...){for(int d=0;d<count;d++)if(staged[d].module){CK(cudaSetDevice(d));cuModuleUnload(staged[d].module);}throw;}return staged;}
static void unload_shared_kernel_image(std::vector<SharedKernelImage>&image){for(size_t d=0;d<image.size();d++)if(image[d].module){CK(cudaSetDevice(int(d)));shared_check_driver(cuModuleUnload(image[d].module),"cuModuleUnload shared kernel");image[d]={};}}
