// 2026-11-03: a worker kernel may exit on its own (rejected request -> error path, exit_reason
// bits). The service must notice, or PARK waits for an acknowledgement that never comes and WAKE
// is a no-op because `started` is still true. A worker stream with no pending work means the
// persistent kernel has exited; then mark it stopped so WAKE relaunches on a reset grid.
template<class W> static bool q38_all_workers_exited(std::vector<W>&dynamic,const char*branch){
 bool any=false;for(size_t d=0;d<dynamic.size();d++){auto&v=dynamic[d];if(!v.running)continue;any=true;
  CK(cudaSetDevice(int(d)));cudaError_t q=cudaStreamQuery(v.stream);if(q==cudaErrorNotReady)return false;
  if(q!=cudaSuccess){fprintf(stderr,"%s_WORKER_STREAM_ERROR,device,%zu,%s\n",branch,d,cudaGetErrorString(q));return false;}}
 if(!any)return false;
 for(size_t d=0;d<dynamic.size();d++){auto&v=dynamic[d];if(!v.running)continue;
  fprintf(stderr,"%s_WORKER_ALREADY_EXITED,device,%zu,seq,%u,status,%u,exit_reason,0x%x\n",branch,d,v.out->seq,v.out->status,v.out->exit_reason);
  v.running=false;}
 return true;}
static void stop_shared_grid(std::vector<SharedDynamicWorker>&dynamic){for(auto&v:dynamic)if(v.running){v.seq=v.host->seq;v.host->mode=2;shared_publish(v,++v.seq);}for(size_t d=0;d<dynamic.size();d++){auto&v=dynamic[d];if(!v.running)continue;if(!shared_await(&v.out->seq,v.seq,10000)||v.out->status||v.out->exit_reason!=2)throw std::runtime_error("resident shared kernel did not acknowledge reload stop");CK(cudaSetDevice(int(d)));CK(cudaStreamSynchronize(v.stream));v.running=false;}}
static void reset_shared_grid(std::vector<SharedDynamicWorker>&dynamic){for(size_t d=0;d<dynamic.size();d++){auto&v=dynamic[d];CK(cudaSetDevice(int(d)));CK(cudaMemset(v.grid,0,sizeof(*v.grid)));std::memset(v.out,0,sizeof(*v.out));v.host->mode=0;_mm_sfence();std::atomic_thread_fence(std::memory_order_seq_cst);}}
static bool valid_shared_bundle(const std::string&d){for(int g=0;g<4;g++){std::string n=d+"/shared."+std::to_string(g)+".";for(auto x:{"gate.bin","up.bin","down.bin"})if(!std::filesystem::is_regular_file(n+x))return false;}return std::filesystem::is_regular_file(d+"/shared_gate_weight.bin");}
