 if(!strcmp(code,"INVALID_LAYER"))printf("{\"request_id\":\"%s\",\"status\":\"error\",\"code\":\"INVALID_LAYER\",\"layer_id\":%d,\"valid_layer_range\":[0,47]}\n",id.c_str(),layer);
